  }
  const titles = new Set(OWNED_FACTS.map((r) => r.ownerTitle));
  for (const text of stringsIn(entry?.pick_steps)) {
    const m = text.match(POINTER);
    if (m && !titles.has(m[1])) out.push({ code: 'POINTER_UNKNOWN_OWNER', field: 'pick_steps', text });
  }
